/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.9 Post delivery note
/// </summary>
[ExtensionOf(tableStr(CustPackingSlipJour))]
final class METCustPackingSlipJourTbl_Extension
{

}

Method.Source:
    /// <summary>
    /// Update shipment and load details on journal table
    /// </summary>
    /// <param name = "_shipmentLoadHeader">METSalesOrderShipmentLoadHeader buffer</param>
    public void METUpdateLoadShipmentId(METSalesOrderShipmentLoadHeader     _shipmentLoadHeader)
    {
        if (this.RecId)
        {
            this.selectForUpdate(true);
            this.skipDataMethods(true);

            ttsbegin;        
            this.METLoadId     = _shipmentLoadHeader.LoadId;
            this.METShipmentId = _shipmentLoadHeader.ShipmentId;
            this.update();
            ttscommit;
        }
               
    }

    /// <summary>
    /// Update shipment and load details on journal table
    /// </summary>
    /// <param name = "_shipmentLoadHeader">METSalesOrderShipmentLoadHeader buffer</param>
    public static void METUpdateLoadShipmentLines(METSalesOrderShipmentLoadHeader     _shipmentLoadHeader)
    {
        METSalesOrderShipmentLoadLines          metSalesOrderShipmentLoadLines;
        SalesLine                               salesLine;
        CustPackingSlipTrans                    packslipTrans;
        CustPackingSlipJour                     packslipJour;
        TmpFrmVirtual                           tmpTable;

        while select salesLine
             join metSalesOrderShipmentLoadLines
                where metSalesOrderShipmentLoadLines.OrderNum == salesLine.SalesId  &&
                    metSalesOrderShipmentLoadLines.LineNum == salesLine.LineNum     &&
                    metSalesOrderShipmentLoadLines.ShipmentId == _shipmentLoadHeader.ShipmentId
        {
            tmpTable.RecordNo = salesLine.RecId;
            tmpTable.Id = salesLine.InventTransId;
            tmpTable.insert();
        }
        ;
                    
        packslipJour.skipDataMethods(true);

        update_recordset packslipJour
            setting METLoadId = _shipmentLoadHeader.LoadId,
                    METShipmentId = _shipmentLoadHeader.ShipmentId
            exists join packslipTrans
                where packslipTrans.SalesId == packslipJour.SalesId                 &&
                    packSlipTrans.DeliveryDate == packslipJour.DeliveryDate         &&
                    packslipTrans.PackingSlipId == packslipJour.PackingSlipId
            join tmpTable
                where tmpTable.Id = packslipTrans.InventTransId;
    }

    /// <summary>
    /// CB626_TMSEngineSOPackingSlip, retrieve the delivery note journal using load and shipment id
    /// </summary>
    /// <param name = "_loadId">Load id</param>
    /// <param name = "_shipmentId">Shipment id</param>
    /// <param name = "_forUpdate">Select record for update</param>
    /// <returns><c>CustPackingSlipJour</c> record</returns>
    public static CustPackingSlipJour METFindLoadShipment(METLoadId _loadId, METShipmentId _shipmentId, boolean   _forUpdate = false)
    {
        CustPackingSlipJour  custPackingSlipJour;

        if (_loadId && _shipmentId)
        {
            custPackingSlipJour.selectForUpdate(_forUpdate);

            select firstonly custPackingSlipJour
                    index hint LoadIdShipmentIdIdx
                       where custPackingSlipJour.METLoadId     == _loadId  &&
                             custPackingSlipJour.METShipmentId == _shipmentId;
        }

        return custPackingSlipJour;
    }
